from collections import deque

def sliding_max(xs, w):
    if w < 1:
        raise ValueError("w must be at least 1")
    if w > len(xs):
        return []

    result = []
    dq = deque()

    for i, x in enumerate(xs):
        # Remove indices that are out of the current window
        if dq and dq[0] < i - w + 1:
            dq.popleft()

        # Remove indices whose values are less than or equal to current value
        while dq and xs[dq[-1]] <= x:
            dq.pop()

        dq.append(i)

        # Once the first window is filled, record the maximum
        if i >= w - 1:
            result.append(xs[dq[0]])

    return result
